package memtable

import (
	"sort"
	"strings"

	"kvstore/internal/sstable"
)

type MemTable struct {
	entries []sstable.Entry
	size    int
	maxSeq  uint64
}

func New() *MemTable {
	return &MemTable{}
}

func (m *MemTable) Add(key, value string, seq uint64, op uint8) {
	e := sstable.Entry{Key: key, Value: value, Seq: seq, Op: op}
	idx := sort.Search(len(m.entries), func(i int) bool {
		if m.entries[i].Key != key {
			return m.entries[i].Key > key
		}
		return m.entries[i].Seq < seq
	})
	m.entries = append(m.entries, sstable.Entry{})
	copy(m.entries[idx+1:], m.entries[idx:])
	m.entries[idx] = e
	m.size += len(key) + len(value)
	if seq > m.maxSeq {
		m.maxSeq = seq
	}
}

func (m *MemTable) Size() int    { return m.size }
func (m *MemTable) Len() int     { return len(m.entries) }
func (m *MemTable) MaxSeq() uint64 { return m.maxSeq }

func (m *MemTable) Get(key string, visibleSeq uint64) (sstable.Entry, bool) {
	idx := sort.Search(len(m.entries), func(i int) bool {
		return m.entries[i].Key >= key
	})
	for i := idx; i < len(m.entries); i++ {
		if m.entries[i].Key != key {
			break
		}
		if m.entries[i].Seq <= visibleSeq && m.entries[i].Op != sstable.OpDeleteRange {
			return m.entries[i], true
		}
	}
	return sstable.Entry{}, false
}

func (m *MemTable) AllEntries() []sstable.Entry {
	out := make([]sstable.Entry, len(m.entries))
	copy(out, m.entries)
	return out
}

func (m *MemTable) EntriesInRange(start, end string) []sstable.Entry {
	var out []sstable.Entry
	for _, e := range m.entries {
		if keyInRange(e.Key, start, end) {
			out = append(out, e)
		}
	}
	return out
}

func (m *MemTable) RangeTombstones() []sstable.Entry {
	var out []sstable.Entry
	for _, e := range m.entries {
		if e.Op == sstable.OpDeleteRange {
			out = append(out, e)
		}
	}
	return out
}

func (m *MemTable) Clear() {
	m.entries = nil
	m.size = 0
	m.maxSeq = 0
}

func keyInRange(key, start, end string) bool {
	if start != "" && key < start {
		return false
	}
	if end != "" && key > end {
		return false
	}
	return true
}

func KeyInRange(key, start, end string) bool {
	return keyInRange(key, start, end)
}

func (m *MemTable) PrefixScan(prefix string) []sstable.Entry {
	var out []sstable.Entry
	for _, e := range m.entries {
		if strings.HasPrefix(e.Key, prefix) {
			out = append(out, e)
		}
	}
	return out
}
