    "hash/crc32"
    "io"
    "os"
    "path/filepath"
    "sort"
    "strconv"
    "strings"
)

const (
    OpPut         = 1
    OpDelete      = 2
    OpDeleteRange = 3

    magic      uint64 = 0x4C534D5453535400
    targetBlock = 4096
)

type Entry struct {
    Key   string
    Value string
    Seq   uint64
    Op    uint8
}

type RangeTombstone struct {
    Start string
    End   string
    Seq   uint64
}

type IndexEntry struct {
    FirstKey string
    Offset   uint64
    Size     uint32
}

type Bloom struct {
    bits uint32
    k    int
    data []byte
}

func NewBloom(n int) *Bloom {
    if n <= 0 {
        return &Bloom{k: 7}
    }
    bits := uint32(n * 10)
    if bits == 0 {
        bits = 1
    }
    return &Bloom{bits: bits, k: 7, data: make([]byte, (bits+7)/8)}
}

func bloomHash(i int, key string) uint32 {
    b := append([]byte{byte(i)}, key...)
    return crc32.ChecksumIEEE(b)
}

func (b *Bloom) Add(key string) {
    if b.bits == 0 {
        return
    }
    for i := 0; i < b.k; i++ {
        h := bloomHash(i, key)
        idx := h % b.bits
        b.data[idx/8] |= 1 << (idx % 8)
    }
}

func (b *Bloom) MayContain(key string) bool {
    if b.bits == 0 {
        return true
    }
    for i := 0; i < b.k; i++ {
        h := bloomHash(i, key)
        idx := h % b.bits
        if b.data[idx/8]&(1<<(idx%8)) == 0 {
            return false
        }
    }
    return true
}

func (b *Bloom) Serialize() []byte {
    var buf []byte
    var u4 [4]byte
    binary.LittleEndian.PutUint32(u4[:], b.bits)
    buf = append(buf, u4[:]...)
    buf = append(buf, b.data...)
    return buf
}

func DeserializeBloom(buf []byte) *Bloom {
    if len(buf) < 4 {
        return &Bloom{k: 7}
    }
    bits := binary.LittleEndian.Uint32(buf[:4])
    data := buf[4:]
    return &Bloom{bits: bits, k: 7, data: data}
}

type Writer struct {
    path     string
    tmpPath  string
    f        *os.File
    buf      *bufio.Writer
    entries  []Entry
    index    []IndexEntry
    offset   uint64
    dataSize uint64
    keyCount uint64
    minSeq   uint64
    maxSeq   uint64
}

func NewWriter(path string) (*Writer, error) {
    tmpPath := path + ".tmp"
    f, err := os.Create(tmpPath)
    if err != nil {
        return nil, err
    }
    return &Writer{
        path:    path,
        tmpPath: tmpPath,
        f:       f,
        buf:     bufio.NewWriter(f),
    }, nil
}

func (w *Writer) Add(e Entry) {
    w.entries = append(w.entries, e)
    w.keyCount++
    if e.Op != OpDeleteRange {
        w.dataSize += uint64(len(e.Key) + len(e.Value))
    }
    if w.keyCount == 1 || e.Seq < w.minSeq {
        w.minSeq = e.Seq
    }
    if e.Seq > w.maxSeq {
        w.maxSeq = e.Seq
    }
}

func encodeEntry(e Entry) []byte {
    var u4 [4]byte
    var u8 [8]byte
    var buf []byte

    binary.LittleEndian.PutUint32(u4[:], uint32(len(e.Key)))
    buf = append(buf, u4[:]...)
    buf = append(buf, e.Key...)
    binary.LittleEndian.PutUint32(u4[:], uint32(len(e.Value)))
    buf = append(buf, u4[:]...)
    buf = append(buf, e.Value...)
    buf = append(buf, e.Op)
    binary.LittleEndian.PutUint64(u8[:], e.Seq)
    buf = append(buf, u8[:]...)
    return buf
}

func (w *Writer) writeBlock(block []byte, firstKey string) error {
    idx := IndexEntry{FirstKey: firstKey, Offset: w.offset, Size: uint32(len(block))}
    w.index = append(w.index, idx)
    if _, err := w.buf.Write(block); err != nil {
        return err
    }
    w.offset += uint64(len(block))
    return nil
}

func (w *Writer) Flush() error {
    sort.SliceStable(w.entries, func(i, j int) bool {
        if w.entries[i].Key != w.entries[j].Key {
            return w.entries[i].Key < w.entries[j].Key
        }
        return w.entries[i].Seq < w.entries[j].Seq
    })

    bloom := NewBloom(int(w.keyCount))
    var block []byte
    var firstKey string

    for _, e := range w.entries {
        if e.Op == OpPut {
            bloom.Add(e.Key)
        }
        enc := encodeEntry(e)
        if len(block) > 0 && len(block)+len(enc) > targetBlock {
            if err := w.writeBlock(block, firstKey); err != nil {
                return err
            }
            block = nil
        }
        if len(block) == 0 {
            firstKey = e.Key
        }
        block = append(block, enc...)
    }
    if len(block) > 0 {
        if err := w.writeBlock(block, firstKey); err != nil {
            return err
        }
    }

    indexOffset := w.offset
    var indexBuf []byte
    var u4 [4]byte
    var u8 [8]byte
    for _, idx := range w.index {
        binary.LittleEndian.PutUint32(u4[:], uint32(len(idx.FirstKey)))
        indexBuf = append(indexBuf, u4[:]...)
        indexBuf = append(indexBuf, idx.FirstKey...)
        binary.LittleEndian.PutUint64(u8[:], idx.Offset)
        indexBuf = append(indexBuf, u8[:]...)
        binary.LittleEndian.PutUint32(u4[:], idx.Size)
        indexBuf = append(indexBuf, u4[:]...)
    }
    if _, err := w.buf.Write(indexBuf); err != nil {
        return err
    }
    w.offset += uint64(len(indexBuf))

    bloomOffset := w.offset
    bloomBytes := bloom.Serialize()
    if _, err := w.buf.Write(bloomBytes); err != nil {
        return err
    }
    w.offset += uint64(len(bloomBytes))

    rangeOffset := w.offset
    var rangeBuf []byte
    var rts []RangeTombstone
    for _, e := range w.entries {
        if e.Op == OpDeleteRange {
            rts = append(rts, RangeTombstone{Start: e.Key, End: e.Value, Seq: e.Seq})
        }
    }
    sort.Slice(rts, func(i, j int) bool {
        return rts[i].Start < rts[j].Start
    })
    binary.LittleEndian.PutUint32(u4[:], uint32(len(rts)))
    rangeBuf = append(rangeBuf, u4[:]...)
    for _, rt := range rts {
        binary.LittleEndian.PutUint32(u4[:], uint32(len(rt.Start)))
        rangeBuf = append(rangeBuf, u4[:]...)
        rangeBuf = append(rangeBuf, rt.Start...)
        binary.LittleEndian.PutUint32(u4[:], uint32(len(rt.End)))
        rangeBuf = append(rangeBuf, u4[:]...)
        rangeBuf = append(rangeBuf, rt.End...)
        binary.LittleEndian.PutUint64(u8[:], rt.Seq)
        rangeBuf = append(rangeBuf, u8[:]...)
    }
    if _, err := w.buf.Write(rangeBuf); err != nil {
        return err
    }
    w.offset += uint64(len(rangeBuf))

    var footer [76]byte
    binary.LittleEndian.PutUint64(footer[0:8], indexOffset)
    binary.LittleEndian.PutUint32(footer[8:12], uint32(len(indexBuf)))
    binary.LittleEndian.PutUint64(footer[12:20], bloomOffset)
    binary.LittleEndian.PutUint32(footer[20:24], uint32(len(bloomBytes)))
    binary.LittleEndian.PutUint64(footer[24:32], rangeOffset)
    binary.LittleEndian.PutUint32(footer[32:36], uint32(len(rangeBuf)))
    binary.LittleEndian.PutUint64(footer[36:44], w.keyCount)
    binary.LittleEndian.PutUint64(footer[44:52], w.dataSize)
    binary.LittleEndian.PutUint64(footer[52:60], w.minSeq)
    binary.LittleEndian.PutUint64(footer[60:68], w.maxSeq)
    binary.LittleEndian.PutUint64(footer[68:76], magic)
    if _, err := w.buf.Write(footer[:]); err != nil {
        return err
    }
    if err := w.buf.Flush(); err != nil {
        return err
    }
    if err := w.f.Close(); err != nil {
        return err
    }
    return os.Rename(w.tmpPath, w.path)
}

type Reader struct {
    path        string
    f           *os.File
    index       []IndexEntry
    rangeTombs  []RangeTombstone
    bloom       *Bloom
    KeyCount    uint64
    DataSize    uint64
    MinSeq      uint64
    MaxSeq      uint64
    FileSeq     uint64
    Level       int
}

func Open(path string) (*Reader, error) {
    f, err := os.Open(path)
    if err != nil {
        return nil, err
    }
    st, err := f.Stat()
    if err != nil {
        f.Close()
        return nil, err
    }
    if st.Size() < 76 {
        f.Close()
        return nil, io.ErrUnexpectedEOF
    }
    var footer [76]byte
    if _, err := f.ReadAt(footer[:], st.Size()-76); err != nil {
        f.Close()
        return nil, err
    }
    magicVal := binary.LittleEndian.Uint64(footer[68:76])
    if magicVal != magic {
        f.Close()
        return nil, io.ErrUnexpectedEOF
    }

    r := &Reader{path: path, f: f}
    r.KeyCount = binary.LittleEndian.Uint64(footer[36:44])
    r.DataSize = binary.LittleEndian.Uint64(footer[44:52])
    r.MinSeq = binary.LittleEndian.Uint64(footer[52:60])
    r.MaxSeq = binary.LittleEndian.Uint64(footer[60:68])

    indexOffset := binary.LittleEndian.Uint64(footer[0:8])
    indexSize := binary.LittleEndian.Uint32(footer[8:12])
    bloomOffset := binary.LittleEndian.Uint64(footer[12:20])
    bloomSize := binary.LittleEndian.Uint32(footer[20:24])
    rangeOffset := binary.LittleEndian.Uint64(footer[24:32])
    rangeSize := binary.LittleEndian.Uint32(footer[32:36])

    indexBuf := make([]byte, indexSize)
    if _, err := f.ReadAt(indexBuf, int64(indexOffset)); err != nil {
        f.Close()
        return nil, err
    }
    r.index = parseIndex(indexBuf)

    bloomBuf := make([]byte, bloomSize)
    if _, err := f.ReadAt(bloomBuf, int64(bloomOffset)); err != nil {
        f.Close()
        return nil, err
    }
    r.bloom = DeserializeBloom(bloomBuf)

    rangeBuf := make([]byte, rangeSize)
    if _, err := f.ReadAt(rangeBuf, int64(rangeOffset)); err != nil {
        f.Close()
        return nil, err
    }
    r.rangeTombs = parseRangeTombstones(rangeBuf)

    base := filepath.Base(path)
    r.FileSeq, r.Level, _ = ParseFilename(base)
    return r, nil
}

func parseIndex(buf []byte) []IndexEntry {
    var out []IndexEntry
    pos := 0
    for pos+4 <= len(buf) {
        kl := binary.LittleEndian.Uint32(buf[pos : pos+4])
        pos += 4
        if pos+int(kl) > len(buf) {
            break
        }
        key := string(buf[pos : pos+int(kl)])
        pos += int(kl)
        if pos+12 > len(buf) {
            break
        }
        off := binary.LittleEndian.Uint64(buf[pos : pos+8])
        sz := binary.LittleEndian.Uint32(buf[pos+8 : pos+12])
        pos += 12
        out = append(out, IndexEntry{FirstKey: key, Offset: off, Size: sz})
    }
    return out
}

func parseRangeTombstones(buf []byte) []RangeTombstone {
    if len(buf) < 4 {
        return nil
    }
    count := binary.LittleEndian.Uint32(buf[:4])
    pos := 4
    var out []RangeTombstone
    for i := uint32(0); i < count; i++ {
        if pos+4 > len(buf) {
            break
        }
        sl := binary.LittleEndian.Uint32(buf[pos : pos+4])
        pos += 4
        if pos+int(sl) > len(buf) {
            break
        }
        start := string(buf[pos : pos+int(sl)])
        pos += int(sl)
        if pos+4 > len(buf) {
            break
        }
        el := binary.LittleEndian.Uint32(buf[pos : pos+4])
        pos += 4
        if pos+int(el) > len(buf) {
            break
        }
        end := string(buf[pos : pos+int(el)])
        pos += int(el)
        if pos+8 > len(buf) {
            break
        }
        seq := binary.LittleEndian.Uint64(buf[pos : pos+8])
        pos += 8
        out = append(out, RangeTombstone{Start: start, End: end, Seq: seq})
    }
    return out
}

func (r *Reader) Close() error {
    if r.f != nil {
        err := r.f.Close()
        r.f = nil
        return err
    }
    return nil
}

func (r *Reader) Path() string        { return r.path }
func (r *Reader) RangeTombstones() []RangeTombstone { return r.rangeTombs }

func (r *Reader) MayContain(key string) bool {
    return r.bloom.MayContain(key)
}

func (r *Reader) findBlock(key string) int {
    idx := sort.Search(len(r.index), func(i int) bool {
        return r.index[i].FirstKey > key
    })
    if idx == 0 {
        return -1
    }
    return idx - 1
}

func (r *Reader) loadBlock(i int) ([]Entry, error) {
    if i < 0 || i >= len(r.index) {
        return nil, nil
    }
    idx := r.index[i]
    buf := make([]byte, idx.Size)
    if _, err := r.f.ReadAt(buf, int64(idx.Offset)); err != nil {
        return nil, err
    }
    return parseBlock(buf), nil
}

func parseBlock(buf []byte) []Entry {
    var out []Entry
    pos := 0
    for pos+4 <= len(buf) {
        kl := binary.LittleEndian.Uint32(buf[pos : pos+4])
        pos += 4
        if pos+int(kl) > len(buf) {
            break
        }
        e := Entry{Key: string(buf[pos : pos+int(kl)])}
        pos += int(kl)
        if pos+4 > len(buf) {
            break
        }
        vl := binary.LittleEndian.Uint32(buf[pos : pos+4])
        pos += 4
        if pos+int(vl) > len(buf) {
            break
        }
        e.Value = string(buf[pos : pos+int(vl)])
        pos += int(vl)
        if pos+9 > len(buf) {
            break
        }
        e.Op = buf[pos]
        pos++
        e.Seq = binary.LittleEndian.Uint64(buf[pos : pos+8])
        pos += 8
        out = append(out, e)
    }
    return out
}

func (r *Reader) PointEntry(key string, visibleSeq uint64) (Entry, bool) {
    if !r.MayContain(key) {
        return Entry{}, false
    }
    bi := r.findBlock(key)
    if bi < 0 {
        return Entry{}, false
    }
    entries, err := r.loadBlock(bi)
    if err != nil {
        return Entry{}, false
    }
    var best Entry
    found := false
    for _, e := range entries {
        if e.Key != key {
            continue
        }
        if e.Seq <= visibleSeq && e.Op != OpDeleteRange {
            if !found || e.Seq > best.Seq {
                best = e
                found = true
            }
        }
    }
    return best, found
}

func (r *Reader) Entries(start, end string) []Entry {
    var out []Entry
    for i := 0; i < len(r.index); i++ {
        if end != "" && r.index[i].FirstKey > end {
            break
        }
        entries, err := r.loadBlock(i)
        if err != nil {
            break
        }
        for _, e := range entries {
            if keyInRange(e.Key, start, end) {
                out = append(out, e)
            }
        }
    }
    return out
}

func (r *Reader) AllEntries() []Entry {
    return r.Entries("", "")
}

func keyInRange(key, start, end string) bool {
    if start != "" && key < start {
        return false
    }
    if end != "" && key > end {
        return false
    }
    return true
}

func ParseFilename(name string) (uint64, int, bool) {
    name = filepath.Base(name)
    if !strings.HasSuffix(name, ".sst") {
        return 0, 0, false
    }
    core := strings.TrimSuffix(name, ".sst")
    parts := strings.Split(core, "_")
    if len(parts) != 2 {
        return 0, 0, false
    }
    seq, err := strconv.ParseUint(parts[0], 10, 64)
    if err != nil {
        return 0, 0, false
    }
    level, err := strconv.Atoi(parts[1])
    if err != nil {
        return 0, 0, false
    }
    return seq, level, true
}

func Filename(seq uint64, level int) string {
    return fmtSeq(seq) + "_" + strconv.Itoa(level) + ".sst"
}

func fmtSeq(seq uint64) string {
    return fmt.Sprintf("%06d", seq)
}
